package slick.test.lifted

import org.junit.Assert.*
import org.junit.Test
import slick.SlickException
import slick.jdbc.{DB2Profile, DerbyProfile, H2Profile, HsqldbProfile, JdbcCapabilities, JdbcProfile, MySQLProfile, OracleProfile, PostgresProfile, SQLiteProfile, SQLServerProfile}

/** Checks the SQL generated by `insertOrUpdate` for tables whose primary key is declared with `primaryKey`
  * (https://github.com/slick/slick/issues/2114) or covers all columns
  * (https://github.com/slick/slick/issues/2206, https://github.com/slick/slick/issues/2207), or consist of a single
  * AutoInc column (https://github.com/slick/slick/issues/3867). */
class InsertOrUpdateStatementTest {

  private class Statements(val profile: JdbcProfile, allColumnsPK: Boolean) {
    import profile.api.*
    class T(tag: Tag) extends Table[(Int, String, String)](tag, "t") {
      def a = column[Int]("a")
      def b = column[String]("b")
      def c = column[String]("c")
      def * = (a, b, c)
      def pk = if (allColumnsPK) primaryKey("t_pk", (a, b, c)) else primaryKey("t_pk", (a, b))
    }
    val ts = TableQuery[T]
    def plain: Seq[String] = ts.insertOrUpdate((1, "x", "y")).statements.toSeq
    def returningAll: Seq[String] = ts.returning(ts).insertOrUpdate((1, "x", "y")).statements.toSeq
  }

  private def statements(profile: JdbcProfile, allColumnsPK: Boolean, returning: Boolean): Seq[String] = {
    val s = new Statements(profile, allColumnsPK)
    if (returning) s.returningAll else s.plain
  }

  private def check(profile: JdbcProfile, allColumnsPK: Boolean, returning: Boolean = false)(expected: Seq[String]): Unit =
    assertEquals(expected, statements(profile, allColumnsPK, returning))

  private val emulatedWithSoftColumn = Seq(
    """select 1 from "t" where "a"=? and "b"=?""",
    """update "t" set "c"=? where "a"=? and "b"=?""",
    """insert into "t" ("a","b","c")  values (?,?,?)"""
  )
  // There is nothing to update when all columns are part of the primary key, so the emulation skips the UPDATE
  private val emulatedAllColumnsPK = Seq(
    """select 1 from "t" where "a"=? and "b"=? and "c"=?""",
    """insert into "t" ("a","b","c")  values (?,?,?)"""
  )

  @Test def testDerby(): Unit = {
    check(DerbyProfile, allColumnsPK = false)(emulatedWithSoftColumn)
    check(DerbyProfile, allColumnsPK = true)(emulatedAllColumnsPK)
  }

  @Test def testPostgres(): Unit = {
    check(PostgresProfile, allColumnsPK = false)(Seq(
      """update "t" set "c"=? where "a"=? and "b"=?; """ +
        """insert into "t" ("a","b","c") select ?,?,? where not exists (select 1 from "t" where "a"=? and "b"=?)"""
    ))
    check(PostgresProfile, allColumnsPK = true)(Seq(
      """insert into "t" ("a","b","c") select ?,?,? where not exists (select 1 from "t" where "a"=? and "b"=? and "c"=?)"""
    ))
    check(PostgresProfile, allColumnsPK = false, returning = true)(emulatedWithSoftColumn)
    check(PostgresProfile, allColumnsPK = true, returning = true)(emulatedAllColumnsPK)
  }

  @Test def testMySQL(): Unit = {
    check(MySQLProfile, allColumnsPK = false)(Seq(
      "insert into `t` (`a`,`b`,`c`)  values (?,?,?) on duplicate key update `a`=VALUES(`a`), `b`=VALUES(`b`), `c`=VALUES(`c`)"
    ))
    check(MySQLProfile, allColumnsPK = true)(Seq(
      "insert into `t` (`a`,`b`,`c`)  values (?,?,?) on duplicate key update `a`=VALUES(`a`), `b`=VALUES(`b`), `c`=VALUES(`c`)"
    ))
  }

  /** A table whose only column is an AutoInc primary key (https://github.com/slick/slick/issues/3867). */
  private class OnlyAutoInc(val profile: JdbcProfile) {
    import profile.api.*
    class T(tag: Tag) extends Table[Int](tag, "t") {
      def id = column[Int]("id", O.PrimaryKey, O.AutoInc)
      def * = id
    }
    val ts = TableQuery[T]
    def plain: Seq[String] = ts.insertOrUpdate(1).statements.toSeq
    def returningId: Seq[String] = ts.returning(ts.map(_.id)).insertOrUpdate(1).statements.toSeq
    def insertOrUpdateAll(): Unit = ts.insertOrUpdateAll(Seq(1))
  }

  private val emulatedOnlyAutoInc = Seq("""select 1 from "t" where "id"=?""", """insert into "t" ("id") values (default)""")
  private val emulatedOnlyAutoIncDefaultValues =
    Seq("""select 1 from "t" where "id"=?""", """insert into "t" default values""")
  private val mergeOnlyAutoInc =
    """s on (t."id"=s."id")   when not matched then insert ("id") values (default)"""

  @Test def testOnlyAutoIncColumn(): Unit = {
    for (profile <- Seq[JdbcProfile](DerbyProfile, H2Profile, PostgresProfile)) {
      assertEquals(emulatedOnlyAutoInc, new OnlyAutoInc(profile).plain)
      assertEquals(emulatedOnlyAutoInc, new OnlyAutoInc(profile).returningId)
    }
    // PostgreSQL's server-side upsert cannot insert such a row, and insertOrUpdateAll has no emulation
    val e = assertThrows(classOf[SlickException], () => new OnlyAutoInc(PostgresProfile).insertOrUpdateAll())
    assertTrue(e.getMessage, e.getMessage.contains("PostgresProfile") && e.getMessage.contains("table t,"))
    assertEquals(
      Seq("insert into `t` (`id`)  values (?) on duplicate key update `id`=`id`"),
      new OnlyAutoInc(MySQLProfile).plain
    )
    assertEquals(emulatedOnlyAutoIncDefaultValues, new OnlyAutoInc(SQLiteProfile).plain)
    assertEquals(emulatedOnlyAutoIncDefaultValues, new OnlyAutoInc(SQLiteProfile).returningId)
    assertEquals(
      Seq("""merge into "t" t using (select ? as "id") s on (t."id"=s."id")   when not matched then insert default values;"""),
      new OnlyAutoInc(SQLServerProfile).plain
    )
    assertEquals(emulatedOnlyAutoIncDefaultValues, new OnlyAutoInc(SQLServerProfile).returningId)
    for (profile <- Seq[JdbcProfile](OracleProfile, DB2Profile, HsqldbProfile)) {
      val merge = new OnlyAutoInc(profile).plain.mkString
      assertTrue(merge, merge.endsWith(mergeOnlyAutoInc))
      assertEquals(emulatedOnlyAutoInc, new OnlyAutoInc(profile).returningId)
    }
  }

  /** The table from https://github.com/slick/slick/issues/1833: a non-AutoInc primary key and a unique `name`. */
  private class Users(val profile: JdbcProfile) {
    import profile.api.*
    class T(tag: Tag) extends Table[(Int, String)](tag, "users") {
      def id = column[Int]("id", O.PrimaryKey)
      def name = column[String]("name")
      def nameIdx = index("users_name", name, unique = true)
      def * = (id, name)
    }
    def statements: Seq[String] = TableQuery[T].insertOrUpdate((1, "Abcd")).statements.toSeq
  }

  /** `ON DUPLICATE KEY UPDATE` fires on any unique key and also assigns the primary key, so a clash on `name` alone
    * moves the other row to the new id instead of failing (https://github.com/slick/slick/issues/1833). */
  @Test def testMySQLUpdatesPrimaryKeyOnUniqueClash(): Unit =
    assertEquals(
      Seq("insert into `users` (`id`,`name`)  values (?,?) on duplicate key update `id`=VALUES(`id`), `name`=VALUES(`name`)"),
      new Users(MySQLProfile).statements
    )

  /** Removing the capability, as documented for a strict primary-key upsert on MySQL, selects the emulation. */
  @Test def testMySQLWithoutUpsertCapability(): Unit = {
    trait StrictUpsertMySQLProfile extends MySQLProfile {
      // Use the client-side emulation (select by primary key, then update or insert)
      // instead of INSERT ... ON DUPLICATE KEY UPDATE
      trait StrictUpsertMySQLAPI extends ProfileAPI {
        override val insertOrUpdateCap = deregister(JdbcCapabilities.insertOrUpdate)
      }
      override val api: StrictUpsertMySQLAPI = new StrictUpsertMySQLAPI {}
    }

    object StrictUpsertMySQLProfile extends StrictUpsertMySQLProfile
    assertEquals(
      Seq(
        "select 1 from `users` where `id`=?",
        "update `users` set `name`=? where `id`=?",
        "insert into `users` (`id`,`name`)  values (?,?)"
      ),
      new Users(StrictUpsertMySQLProfile).statements
    )
  }

  /** SQLite's UPSERT names the primary key as the conflict target, so a clash on another unique column fails
    * instead of deleting the other row as INSERT OR REPLACE did (https://github.com/slick/slick/issues/3846). */
  @Test def testSQLite(): Unit = {
    check(SQLiteProfile, allColumnsPK = false)(Seq(
      """insert into "t" as "upsert_target" ("a","b","c")  values (?,?,?) on conflict ("a","b") do update set "c"=excluded."c""""
    ))
    check(SQLiteProfile, allColumnsPK = true)(Seq(
      """insert into "t" as "upsert_target" ("a","b","c")  values (?,?,?) on conflict ("a","b","c") do nothing"""
    ))
    check(SQLiteProfile, allColumnsPK = false, returning = true)(emulatedWithSoftColumn)
    check(SQLiteProfile, allColumnsPK = true, returning = true)(emulatedAllColumnsPK)
  }

  /** Tables with an AutoInc column keep the client-side emulation on SQLite. */
  @Test def testSQLiteAutoInc(): Unit = {
    import SQLiteProfile.api.*
    class T(tag: Tag) extends Table[(Int, String)](tag, "t") {
      def id = column[Int]("id", O.PrimaryKey, O.AutoInc)
      def name = column[String]("name")
      def * = (id, name)
    }
    assertEquals(
      Seq(
        """select 1 from "t" where "id"=?""",
        """update "t" set "name"=? where "id"=?""",
        """insert into "t" ("name")  values (?)"""
      ),
      TableQuery[T].insertOrUpdate((1, "a")).statements.toSeq
    )
  }

  @Test def testSQLServer(): Unit = {
    check(SQLServerProfile, allColumnsPK = false)(Seq(
      """merge into "t" t using (select ? as "a",? as "b",? as "c") s on (t."a"=s."a" and t."b"=s."b") """ +
        """when matched then update set t."c"=s."c"  when not matched then insert ("a", "b", "c") """ +
        """values (s."a", s."b", s."c");"""
    ))
    check(SQLServerProfile, allColumnsPK = true)(Seq(
      """merge into "t" t using (select ? as "a",? as "b",? as "c") s on (t."a"=s."a" and t."b"=s."b" and t."c"=s."c")  """ +
        """ when not matched then insert ("a", "b", "c") values (s."a", s."b", s."c");"""
    ))
  }

  @Test def testMergeProfiles(): Unit =
    for (profile <- Seq[JdbcProfile](OracleProfile, DB2Profile, HsqldbProfile)) {
      val withSoft = statements(profile, allColumnsPK = false, returning = false).mkString
      assertTrue(withSoft, withSoft.contains("""on (t."a"=s."a" and t."b"=s."b")"""))
      assertTrue(withSoft, withSoft.contains("""when matched then update set t."c"=s."c""""))
      val allPK = statements(profile, allColumnsPK = true, returning = false).mkString
      assertTrue(allPK, allPK.contains("""on (t."a"=s."a" and t."b"=s."b" and t."c"=s."c")"""))
      assertFalse(allPK, allPK.contains("when matched"))
      assertEquals(emulatedWithSoftColumn, statements(profile, allColumnsPK = false, returning = true))
      assertEquals(emulatedAllColumnsPK, statements(profile, allColumnsPK = true, returning = true))
    }
}
